----- CELL BUFGP -----

library IEEE;
use IEEE.STD_LOGIC_1164.all;

entity BUFGP is
  port(
    O : out std_ulogic;

    I : in std_ulogic
    );
end BUFGP;

architecture BUFGP_V of BUFGP is
begin
  O <= TO_X01(I);
end BUFGP_V;


