    function xor_6 (
      vec : in unsigned (5 downto 0)
    ) return std_ulogic is
    variable xor6 : std_ulogic := '0';
    begin
      xor6 := vec(5) xor vec(4) xor vec(3) xor vec(2) xor vec(1) xor vec(0);
      return xor6;
    end;

