  INIPROC : process
  variable Message : line;
  variable attr_err : boolean := false;
  begin
    -------- ACASCREG check
  if((xil_attr_test) or
     ((ACASCREG /= 1) and 
      (ACASCREG /= 0) and 
      (ACASCREG /= 2))) then
    attr_err := true;
    Write ( Message, string'("Error : [Unisim "));
    Write ( Message, string'(MODULE_NAME));
    Write ( Message, string'("-101] ACASCREG attribute is set to "));
    Write ( Message, ACASCREG);
    Write ( Message, string'(". Legal values for this attribute are "));
    Write ( Message, string'("1, "));
    Write ( Message, string'("0 or "));
    Write ( Message, string'("2. "));
    Write ( Message, string'("Instance "));
    Write ( Message, string'(DSP48E2_V'INSTANCE_NAME));
    writeline(output, Message);
    DEALLOCATE (Message);
  end if;
    -------- ADREG check
  if((xil_attr_test) or
     ((ADREG /= 1) and 
      (ADREG /= 0))) then
    attr_err := true;
    Write ( Message, string'("Error : [Unisim "));
    Write ( Message, string'(MODULE_NAME));
    Write ( Message, string'("-102] ADREG attribute is set to "));
    Write ( Message, ADREG);
    Write ( Message, string'(". Legal values for this attribute are "));
    Write ( Message, string'("1 or "));
    Write ( Message, string'("0. "));
    Write ( Message, string'("Instance "));
    Write ( Message, string'(DSP48E2_V'INSTANCE_NAME));
    writeline(output, Message);
    DEALLOCATE (Message);
  end if;
    -------- ALUMODEREG check
  if((xil_attr_test) or
     ((ALUMODEREG /= 1) and 
      (ALUMODEREG /= 0))) then
