----- CELL FIFO18E1 -----

library IEEE;
use IEEE.STD_LOGIC_1164.all;

library unisim;
use unisim.VCOMPONENTS.all;
use unisim.vpkg.all;

entity FIFO18E1 is

generic (

    ALMOST_FULL_OFFSET      : bit_vector := X"0080";
    ALMOST_EMPTY_OFFSET     : bit_vector := X"0080"; 
    DATA_WIDTH              : integer    := 4;
    DO_REG                  : integer    := 1;
    EN_SYN                  : boolean    := FALSE;
    FIFO_MODE               : string     := "FIFO18";
    FIRST_WORD_FALL_THROUGH : boolean    := FALSE;
    INIT                    : bit_vector := X"000000000";
    IS_RDCLK_INVERTED       : bit := '0';
    IS_RDEN_INVERTED        : bit := '0';
    IS_RSTREG_INVERTED      : bit := '0';
    IS_RST_INVERTED         : bit := '0';
    IS_WRCLK_INVERTED       : bit := '0';
    IS_WREN_INVERTED        : bit := '0';
    SIM_DEVICE              : string     := "7SERIES";
    SRVAL                   : bit_vector := X"000000000"
    
  );

port (

    ALMOSTEMPTY    : out std_ulogic;
    ALMOSTFULL     : out std_ulogic;
    DO             : out std_logic_vector (31 downto 0);
    DOP            : out std_logic_vector (3 downto 0);
    EMPTY          : out std_ulogic;
    FULL           : out std_ulogic;
    RDCOUNT        : out std_logic_vector (11 downto 0);
    RDERR          : out std_ulogic;
    WRCOUNT        : out std_logic_vector (11 downto 0);
    WRERR          : out std_ulogic;

    DI             : in  std_logic_vector (31 downto 0);
    DIP            : in  std_logic_vector (3 downto 0);
    RDCLK          : in  std_ulogic;
    RDEN           : in  std_ulogic;
    REGCE          : in  std_ulogic;
    RST            : in  std_ulogic;
    RSTREG         : in  std_ulogic;
    WRCLK          : in  std_ulogic;
    WREN           : in  std_ulogic    
  );

end FIFO18E1;
                                                                        
architecture FIFO18E1_V of FIFO18E1 is

  component FF18_INTERNAL_VHDL

    generic(

    ALMOST_FULL_OFFSET      : bit_vector := X"0080";
    ALMOST_EMPTY_OFFSET     : bit_vector := X"0080"; 
    DATA_WIDTH              : integer    := 4;
    DO_REG                  : integer    := 1;
    EN_ECC_READ             : boolean    := FALSE;
    EN_ECC_WRITE            : boolean    := FALSE;    
    EN_SYN                  : boolean    := FALSE;
    FIFO_MODE               : string     := "FIFO36";
    FIFO_SIZE               : integer    := 36;
    FIRST_WORD_FALL_THROUGH : boolean    := FALSE;
    INIT                    : bit_vector := X"000000000000000000";
    SIM_DEVICE              : string     := "7SERIES";
    SRVAL                   : bit_vector := X"000000000000000000"
    );

  port(
    ALMOSTEMPTY          : out std_ulogic;
    ALMOSTFULL           : out std_ulogic;
    DBITERR              : out std_ulogic;
    DO                   : out std_logic_vector (63 downto 0);
    DOP                  : out std_logic_vector (7 downto 0);
    ECCPARITY            : out std_logic_vector (7 downto 0);
    EMPTY                : out std_ulogic;
    FULL                 : out std_ulogic;
    RDCOUNT              : out std_logic_vector (12 downto 0);
    RDERR                : out std_ulogic;
    SBITERR              : out std_ulogic;
    WRCOUNT              : out std_logic_vector (12 downto 0);
    WRERR                : out std_ulogic;

    DI                   : in  std_logic_vector (63 downto 0);
    DIP                  : in  std_logic_vector (7 downto 0);
    INJECTDBITERR        : in  std_ulogic;
    INJECTSBITERR        : in  std_ulogic;
    RDCLK                : in  std_ulogic;
    RDEN                 : in  std_ulogic;
    REGCE                : in  std_ulogic;
    RST                  : in  std_ulogic;
    RSTREG               : in  std_ulogic;
    WRCLK                : in  std_ulogic;
    WREN                 : in  std_ulogic
    );

  end component;

    
  constant SYNC_PATH_DELAY : time := 100 ps;
  signal GND_4 : std_logic_vector(3 downto 0) := (others => '0');
  signal GND_32 : std_logic_vector(31 downto 0) := (others => '0');
  signal OPEN_1 : std_logic_vector(0 downto 0);
  signal OPEN_4 : std_logic_vector(3 downto 0);
  signal OPEN_32 : std_logic_vector(31 downto 0);
  signal OPEN_8 : std_logic_vector(7 downto 0);
  signal do_dly : std_logic_vector(31 downto 0) :=  (others => '0');
  signal dop_dly : std_logic_vector(3 downto 0) :=  (others => '0');
  signal almostfull_dly : std_ulogic := '0';
  signal almostempty_dly : std_ulogic := '0';
  signal empty_dly : std_ulogic := '0';
  signal full_dly : std_ulogic := '0';
  signal rderr_dly : std_ulogic := '0';
  signal wrerr_dly : std_ulogic := '0';
  signal rdcount_dly : std_logic_vector(11 downto 0) :=  (others => '0');
  signal wrcount_dly : std_logic_vector(11 downto 0) :=  (others => '0');
  signal sbiterr_dly : std_ulogic := '0';
  signal dbiterr_dly : std_ulogic := '0';
  signal eccparity_dly : std_logic_vector(7 downto 0) :=  (others => '0');
  signal RDCLK_in : std_ulogic;
  signal RDEN_in : std_ulogic;
  signal RSTREG_in : std_ulogic;
  signal RST_in : std_ulogic;
  signal WRCLK_in : std_ulogic;
  signal WREN_in : std_ulogic;
  signal IS_RDCLK_INVERTED_reg : std_ulogic := TO_X01(IS_RDCLK_INVERTED);
  signal IS_RDEN_INVERTED_reg : std_ulogic := TO_X01(IS_RDEN_INVERTED);
  signal IS_RSTREG_INVERTED_reg : std_ulogic := TO_X01(IS_RSTREG_INVERTED);
  signal IS_RST_INVERTED_reg : std_ulogic := TO_X01(IS_RST_INVERTED);
  signal IS_WRCLK_INVERTED_reg : std_ulogic := TO_X01(IS_WRCLK_INVERTED);
  signal IS_WREN_INVERTED_reg : std_ulogic := TO_X01(IS_WREN_INVERTED);
  signal DI_in : std_logic_vector(31 downto 0);
  signal DIP_in : std_logic_vector(3 downto 0);
  signal REGCE_in : std_ulogic;

  
  function INIT_SRVAL_SDP (
    input_a : bit_vector(35 downto 0);
    input_b : bit_vector(35 downto 0))
    return bit_vector is variable out_init_srval : bit_vector(71 downto 0);
  begin

    if (FIFO_MODE = "FIFO18_36") then
      out_init_srval := input_a & input_b(35 downto 34) & input_b(17 downto 16) & input_b(33 downto 18) & input_b(15 downto 0);
    else
      out_init_srval := input_a & input_b;
    end if;

    return out_init_srval;  
                         
  end;
  
  
begin

  DI_in <= DI xor X"00000000";
  DIP_in <= DIP xor X"0";
  REGCE_in <= REGCE xor '0';

  RDCLK_in <= RDCLK xor IS_RDCLK_INVERTED_reg;
  RDEN_in <= RDEN xor IS_RDEN_INVERTED_reg;
  RSTREG_in <= RSTREG xor IS_RSTREG_INVERTED_reg;
  RST_in <= RST xor IS_RST_INVERTED_reg;
  WRCLK_in <= WRCLK xor IS_WRCLK_INVERTED_reg;
  WREN_in <= WREN xor IS_WREN_INVERTED_reg;

  
FIFO18E1_inst : FF18_INTERNAL_VHDL
  generic map (
    ALMOST_EMPTY_OFFSET => ALMOST_EMPTY_OFFSET, 
    ALMOST_FULL_OFFSET => ALMOST_FULL_OFFSET,
    DATA_WIDTH => DATA_WIDTH,
    DO_REG => DO_REG,
    EN_SYN => EN_SYN,
    FIFO_SIZE => 18,
    FIRST_WORD_FALL_THROUGH => FIRST_WORD_FALL_THROUGH,
    INIT => INIT_SRVAL_SDP(X"000000000", INIT),
    SIM_DEVICE => SIM_DEVICE,
    SRVAL => INIT_SRVAL_SDP(X"000000000", SRVAL)
    )

  port map (
    ALMOSTEMPTY => almostempty_dly,
    ALMOSTFULL => almostfull_dly,
    DBITERR => OPEN,
    DO(31 downto 0) => do_dly,
    DO(63 downto 32) => OPEN_32,
    DOP(3 downto 0) => dop_dly,
    DOP(7 downto 4) => OPEN_4,
    ECCPARITY => OPEN_8,
    EMPTY => empty_dly,
    FULL => full_dly,
    RDCOUNT(11 downto 0) => rdcount_dly,
    RDCOUNT(12 downto 12) => OPEN_1,
    RDERR => rderr_dly,
    SBITERR => OPEN,
    WRCOUNT(11 downto 0) => wrcount_dly,
    WRCOUNT(12 downto 12) => OPEN_1,
    WRERR => wrerr_dly,

    DI(31 downto 0) => DI_in,
    DI(63 downto 32) => GND_32,
    DIP(3 downto 0) => DIP_in,
    DIP(7 downto 4) => GND_4,
    INJECTDBITERR => '0',
    INJECTSBITERR => '0',
    RDCLK => RDCLK_in,
    RDEN => RDEN_in,
    REGCE => REGCE_in,
    RST => RST_in,
    RSTREG => RSTREG_in,
    WRCLK => WRCLK_in,
    WREN => WREN_in
    );

   prcs_initialize:process
     variable first_time        : boolean    := true;

     begin
       if (first_time) then

         case DATA_WIDTH is
            when 4 | 9 | 18 | 36 => null;
            when others =>
                    GenericValueCheckMessage
                      ( HeaderMsg            => " Attribute Syntax Error ",
                        GenericName          => " DATA_WIDTH ",
                        EntityName           => "FIFO18E1",
                        GenericValue         => DATA_WIDTH,
                        Unit                 => "",
                        ExpectedValueMsg     => " The Legal values for this attribute are ",
                        ExpectedGenericValue => " 4, 9, 18 and 36",
                        TailMsg              => "",
                        MsgSeverity          => failure
                        );
         end case;


         if (not(FIFO_MODE = "FIFO18" or FIFO_MODE = "FIFO18_36")) then

           GenericValueCheckMessage
             ( HeaderMsg            => " Attribute Syntax Error : ",
               GenericName          => " FIFO_MODE ",
               EntityName           => "FIFO18E1",
               GenericValue         => FIFO_MODE,
               Unit                 => "",
               ExpectedValueMsg     => " The Legal values for this attribute are ",
               ExpectedGenericValue => " FIFO18 or FIFO18_36 ",
               TailMsg              => "",
               MsgSeverity          => failure
               );
         end if;

         
         if(DATA_WIDTH = 36 xor FIFO_MODE = "FIFO18_36") then
          assert false
          report "DRC Error : The attribute DATA_WIDTH must be set to 36 when attribute FIFO_MODE = FIFO18_36."
          severity failure;
         end if;

         
         first_time := false;
       end if;
       wait;
   end process prcs_initialize;

     
   prcs_output_wtiming: process (do_dly, dop_dly, almostempty_dly, almostfull_dly, empty_dly, full_dly, rdcount_dly, wrcount_dly, rderr_dly, wrerr_dly)
   begin  -- process prcs_output_wtiming

     ALMOSTEMPTY <= almostempty_dly after SYNC_PATH_DELAY;
     ALMOSTFULL <= almostfull_dly after SYNC_PATH_DELAY;
     DO <= do_dly after SYNC_PATH_DELAY;
     DOP <= dop_dly after SYNC_PATH_DELAY;
     EMPTY <= empty_dly after SYNC_PATH_DELAY;
     FULL <= full_dly after SYNC_PATH_DELAY;
     RDCOUNT <= rdcount_dly after SYNC_PATH_DELAY;
     RDERR <= rderr_dly after SYNC_PATH_DELAY;
     WRCOUNT <= wrcount_dly after SYNC_PATH_DELAY;
     WRERR <= wrerr_dly after SYNC_PATH_DELAY;
     
   end process prcs_output_wtiming;

end FIFO18E1_V;
