    signal IS_RDCLK_INVERTED_BIN : std_ulogic := '0';
    signal IS_RDEN_INVERTED_BIN : std_ulogic := '0';
    signal IS_RSTREG_INVERTED_BIN : std_ulogic := '0';
    signal IS_RST_INVERTED_BIN : std_ulogic := '0';
