   --vc  constant COUNT_WIDTH : integer := 14;
   --vc vc_val2[12:0]= 1FFF = 8191 need increase width by 1-bit to comport value 8192
   --vc vc_val2[13:0]= 3FFF = 16383
   signal vc_val : unsigned (COUNT_WIDTH-1 downto 0) := (others => '0');
   signal vc_val2 : unsigned (COUNT_WIDTH-1 downto 0) := (others => '0');

   signal prog_empty_val : unsigned (COUNT_WIDTH-2 downto 0) := (others => '0');
