  --            '1' when (SIM_DEVICE = "7SERIES") else
--	      '0' when (SIM_DEVICE = "VERSAL" or SIM_DEVICE = "VERSAL_ES1" or SIM_DEVICE = "VERSAL_ES2");
prcs_sim_device : process(SIM_DEVICE_BIN)
begin
    case SIM_DEVICE_BIN is
        when SIM_DEVICE_ULTRASCALE => 
		out_val <= '0';
		out_b_val <= 'X';
        when SIM_DEVICE_7SERIES => 
	        out_val <= '1';
		out_b_val <= '1';
        when others =>
	        out_val <= '0';
		out_b_val <= '0';
    end case;
end process;

   prcs_output : process (IBUFDISABLE_in, I_in, IB_in, USE_IBUFDISABLE_BIN, DQS_BIAS_BIN)
      variable IBUFDISABLE_BIN   : std_ulogic := '0';
   begin
     IBUFDISABLE_BIN := (IBUFDISABLE_in and USE_IBUFDISABLE_BIN);
     if(IBUFDISABLE_BIN = '1') then
       O_out <= out_val;
       OB_out <= out_b_val;
     elsif (IBUFDISABLE_BIN = '0') then
       if ((I_in = '1' or I_in = 'H') and (IB_in = '0' or IB_in = 'L')) then
          O_out <= '1';
	  OB_out <= '0';
       elsif ((I_in = '0' or I_in = 'L') and (IB_in = '1' or IB_in = 'H')) then
          O_out <= '0';
	  OB_out <= '1';
       elsif ((I_in = 'Z' or I_in = '0' or I_in = 'L') and (IB_in = 'Z' or IB_in = '1' or IB_in = 'H')) then
          if (DQS_BIAS_BIN = '1') then
            O_out <= '0';
	    OB_out <= '1';
          else
            O_out <= 'X';
	    OB_out <= 'X';
          end if;
       elsif ((I_in = 'X' or I_in = 'U') and (IB_in = 'X' or IB_in = 'U' )) then
         O_out <= 'X';
	 OB_out <= 'X';
       end if;
     end if;
   end process;

-- end behavioral model

