----- CELL IBUF_ANALOG -----

library IEEE;
use IEEE.NUMERIC_STD.all;
use IEEE.STD_LOGIC_1164.all;

entity IBUF_ANALOG is
  port (
    O                    : out std_ulogic;
    I                    : in std_ulogic
  );
end IBUF_ANALOG;

architecture IBUF_ANALOG_V of IBUF_ANALOG is

