  -- begin behavioral model declarations
 signal out_val : std_ulogic := '1';
 
  -- end behavioral model declarations
  
  begin
  glblGSR     <= TO_X01(GSR);
  
  O <= O_out;
  IO <= IO_out;
  IOB <= IOB_out;
  
