      SLEW_FAST when (SLEW = "FAST") else
      SLEW_MEDIUM when (SLEW = "MEDIUM") else
      SLEW_SLOW;
  
  USE_IBUFDISABLE_BIN <= 
      USE_IBUFDISABLE_TRUE when (USE_IBUFDISABLE = "TRUE") else
      USE_IBUFDISABLE_FALSE when (USE_IBUFDISABLE = "FALSE") else
      USE_IBUFDISABLE_TRUE;
  
  
  INIPROC : process
