entity IOBUFDS_INTERMDISABLE is
  generic (
    DIFF_TERM : string := "FALSE";
    DQS_BIAS : string := "FALSE";
    IBUF_LOW_PWR : string := "TRUE";
    IOSTANDARD : string := "DEFAULT";
    SIM_DEVICE : string := "7SERIES";
    SLEW : string := "SLOW";
    USE_IBUFDISABLE : string := "TRUE"
  );
  
  port (
    O                    : out std_ulogic;
    IO                   : inout std_ulogic;
    IOB                  : inout std_ulogic;
    I                    : in std_ulogic;
    IBUFDISABLE          : in std_ulogic;
    INTERMDISABLE        : in std_ulogic;
    T                    : in std_ulogic
  );
end IOBUFDS_INTERMDISABLE;

architecture IOBUFDS_INTERMDISABLE_V of IOBUFDS_INTERMDISABLE is

  constant MODULE_NAME : string := "IOBUFDS_INTERMDISABLE";
  constant OUTCLK_DELAY : time := 100 ps;
  
-- Parameter encodings and registers
  constant DIFF_TERM_FALSE : std_ulogic := '0';
  constant DIFF_TERM_TRUE : std_ulogic := '1';
  constant DQS_BIAS_FALSE : std_ulogic := '0';
