--    03/23/04 - Initial version.
--    05/09/05 - Fixed CR#198911

----- CELL KEEPER -----

library IEEE;
use IEEE.STD_LOGIC_1164.all;

entity KEEPER is
  port(
    O : inout std_ulogic := 'W'
    );
end KEEPER;

architecture KEEPER_V of KEEPER is
begin
  process (O)
  begin
    if (O'event) then
      if (O = '1') then
        O <= 'H';
      elsif (O = '0') then
        O <= 'L';
      elsif (O = 'X') then
        O <= 'W';        
      end if;
    end if;
  end process;
end KEEPER_V;


