    CLKOUT4_PHASE : real := 0.000;
    CLKOUT4_USE_FINE_PS : boolean := FALSE;
    CLKOUT5_DIVIDE : integer := 1;
    CLKOUT5_DUTY_CYCLE : real := 0.500;
    CLKOUT5_PHASE : real := 0.000;
