----- CELL OBUFDS -----

library IEEE;
use IEEE.STD_LOGIC_1164.all;

entity OBUFDS is
  generic(
      CAPACITANCE : string     := "DONT_CARE";
      IOSTANDARD  : string     := "DEFAULT";
      SLEW        : string     := "SLOW"
    );

  port(
    O  : out std_ulogic;
    OB : out std_ulogic;

    I : in std_ulogic
    );
end OBUFDS;

architecture OBUFDS_V of OBUFDS is
begin
  FunctionalBehavior    : process (I)
    variable O_zd  : std_logic;
    variable OB_zd : std_logic;
  begin
    O_zd  := TO_X01(I);
    OB_zd := (not O_zd);
    O  <= O_zd;
    OB <= OB_zd;
  end process;
end OBUFDS_V;


