        QWC		=> qwc,
        QRD		=> qrd,
        RD_GAP1		=> rd_gap1,
        BUFG_CLK	=> CLK,
        BUFO_CLK	=> BUFO,
        RST_BUFG_P	=> rst_bufg_p,
        RST_BUFO_P	=> rst_bufo_p,
