  CLKPERFDELAY_dly	 <= CLKPERFDELAY   ;
  D1_dly         	 <= D1             ;
  D2_dly         	 <= D2             ;
  D3_dly         	 <= D3             ;
  D4_dly         	 <= D4             ;
  D5_dly         	 <= D5             ;
  D6_dly         	 <= D6             ;
  OCE_dly        	 <= OCE            ;
  ODV_dly        	 <= ODV            ;
  RST_dly        	 <= RST            ;
