  function INIT_SRVAL_SDP (
    input_a, input_b: bit_vector
  )
    return bit_vector is 
      variable input_a_20     : bit_vector(0 to 19);
      variable input_b_20     : bit_vector(0 to 19);
      variable out_init_srval : bit_vector(0 to 39);
  begin
    
  -- if  (input_a'length /=input_b'length or input_a'length/=18 or input_a'length/=20)then
  --   assert FALSE report "[RAMB18E1] ERROR: INIT_A/B, SRVAL_A/B sizes can be either 18 or 20 and A and B need to be equal."
  --   severity error;
  -- end if;
    
    if(input_a'length=18) then
      input_a_20:= ("00" & input_a(0 to 17));
    else
      input_a_20 := input_a(0 to 19);
    end if;
    
    if(input_b'length=18) then
      input_b_20:= ("00" & input_b(0 to 17));
    else
      input_b_20 := input_b(0 to 19);
    end if;

    if (READ_WIDTH_A = 36) then
      out_init_srval := "0000" & input_b_20(2 to 3) & input_a_20(2 to 3) & input_b_20(4 to 19) & input_a_20(4 to 19);
    else
      out_init_srval := input_b_20 & input_a_20;
    end if;

    return out_init_srval;  
                         
  end;

  
