                DOPA(3 downto 2) => dopb_dly,
                DOPA(7 downto 4) => OPEN_DOPA_4,
                DOPB => OPEN,
                CASCADEOUTA => OPEN,
                CASCADEOUTB => OPEN,
                CASCADEINA => GND_1,
                CASCADEINB => GND_1,
                REGCEA => REGCEAREGCE_in,
                REGCEB => REGCEB_in,
                RSTREGA => RSTREGARSTREG_in,
                RSTREGB => RSTREGB_in,
                RDADDRECC => OPEN,
                INJECTDBITERR => GND_1,
                INJECTSBITERR => GND_1,
                DBITERR => OPEN,
                SBITERR => OPEN,
                ECCPARITY => OPEN
                );

    end generate WWBlt18;
    
  end generate SDP;
    
  prcs_output_wtiming: process (doa_dly, dob_dly, dopa_dly, dopb_dly)
   begin  -- process prcs_output_wtiming

     DOADO <= doa_dly after SYNC_PATH_DELAY;
     DOPADOP <= dopa_dly after SYNC_PATH_DELAY;
     DOBDO <= dob_dly after SYNC_PATH_DELAY;
     DOPBDOP <= dopb_dly after SYNC_PATH_DELAY;
     
   end process prcs_output_wtiming;

end RAMB18E1_V;
