                  end if;

                  if (seq = "00") then
                    prcd_chk_for_col_msg (viol_type_tmp, wea_tmp(0), web_tmp(0), addra_tmp, addrb_tmp, ox_wr_wr_msg, ox_wra_rdb_msg, ox_wrb_rda_msg, chk_col_same_clk_tmp, chk_ox_same_clk_tmp, chk_ox_msg_tmp);
