                prcd_ox_wr_ram_b (viol_type, "10", wea_dly, web_dly, dib_ecc_col, dipb_dly, addra_dly, addrb_dly, mem, memp, col_wr_wr_msg, col_wra_rdb_msg, col_wrb_rda_msg, chk_col_same_clk, chk_ox_same_clk, chk_ox_msg);

