              if (EN_ECC_WRITE = TRUE or EN_ECC_READ = TRUE) then

                if (injectdbiterr_dly = '1') then
                  dib_ecc_col(30) := not(dib_ecc_col(30));
                  dib_ecc_col(62) := not(dib_ecc_col(62));
