   gsr_cmd_out_pulse_p0 :  process  begin
    if (rw_en(0)  =  '0') then
       gsr_cmd_out_pulse(0) <= '0';
    elsif (rising_edge(gsr_cmd_out(0))) then
       gsr_cmd_out_pulse(0) <= '1';
       wait until (rising_edge(cclk_in ));
       wait until (rising_edge(cclk_in ));
       gsr_cmd_out_pulse(0) <=  '0';
   end if;
      wait on gsr_cmd_out(0), rw_en(0);
   end process;

