        DOUT_B_out <= CAS_IN_DOUT_B_in;
      end if;
    elsif ((OREG_ECC_B_BIN = OREG_ECC_B_TRUE)) then
      DOUT_B_out <= DOUT_B_reg;
    elsif ((EN_ECC_RD_B_BIN = EN_ECC_RD_B_TRUE)) then
      DOUT_B_out <= ram_data_b_ecc;
    elsif (data_B_enable = '1') then
