    wait on RST_B_async, RST_B_sync, glblGSR, CAS_IN_DOUT_B_in, CAS_IN_DOUT_B_reg, ram_data_b_ecc, DOUT_B_reg, ram_data_b_reg, ram_data_b_lat, cas_out_mux_sel_b;
