      if (glblGSR = '1' or RST_A_in = '1' or 
          a_sleep = '1' or DEEPSLEEP_in = '1' or SLEEP_in = '1' or auto_sleep = '1' or
          shut_down = '1' or SHUTDOWN_in = '1') then
        ram_ce_a <= '0';
      else
        ram_ce_a <= ram_ce_a_int;
      end if;
    elsif (glblGSR = '1') then
      ram_ce_a <= '0';
    end if;
  end process;

